actions.script:
def input
try { input=new groovy.json.JsonSlurper().parseText(itemsJson) } catch(Exception ignored) { input=null }
if (!(input instanceof List) || !input || input.size()>100) { ec.message.addError('Add 1 to 100 valid items before printing a bill.'); return }
def mode=salesModeId ? ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',salesModeId).one() : null
if(salesModeId && (!mode || mode.isActive!='Y' || (mode.organizationPartyId && mode.organizationPartyId!=scope.organizationPartyId))) {
    ec.message.addError('Choose an active sales mode.'); return
}
def waiter=waiterId ? ec.entity.find('zenith.erp.pos.Waiter').condition('waiterId',waiterId)
    .condition('organizationPartyId',scope.organizationPartyId).condition('isActive','Y').one() : null
if(waiterId && !waiter) { ec.message.addError('Choose an active waiter.'); return }
def products=[], taxInputs=[]
for (def item : input) {
    def p=item instanceof Map && item.productId ? ec.entity.find('mantle.product.Product').condition('productId',item.productId).one() : null
    BigDecimal qty=null
    try { qty=new BigDecimal(String.valueOf(item instanceof Map ? item.quantity : null)) } catch(Exception ignored) { }
    if (!p || p.ownerPartyId!=scope.organizationPartyId || p.productTypeEnumId!='PtAsset' || qty==null || qty<=0 || qty>1000000) { ec.message.addError('The order contains an invalid product or quantity.'); return }
    def price=p.mrpAmount as BigDecimal
    def mp=mode ? ec.service.sync().name('zenith.pos.PosServices.resolve#PosModePrice')
        .parameters([productId:p.productId,salesModeId:salesModeId,product:p]).call() : [:]
    if(mp.blocked) { ec.message.addError(mp.blockReason); return }
    if(mp.isFixed) price=mp.unitPrice
    else if(mode) {
        def priced=ec.service.sync().name('zenith.pricing.PricingServices.calculate#Price')
            .parameters([productId:p.productId,quantity:qty,organizationPartyId:scope.organizationPartyId,salesChannelEnumId:'ScPos']).call()
        if(priced?.unitPrice>0) price=priced.unitPrice
    }
    if(!mode && item.manualPrice=='Y') {
        try { price=new BigDecimal(String.valueOf(item.unitPrice)) } catch(Exception ignored) { price=null }
    }
    if(price==null || price<0 || price>10000000 || price.scale()>2) { ec.message.addError('Enter a valid item price before printing.'); return }
    def discount=(price*qty*((mp.discountPercent ?: 0) as BigDecimal)/100).setScale(2,java.math.RoundingMode.HALF_UP)
    products.add([product:p,qty:qty,price:price,discount:discount])
    taxInputs.add([productId:p.productId,productTaxCode:p.productTaxCode,taxCategoryId:p.taxCategoryId,quantity:qty,unitAmount:price,discountAmount:discount,isTaxInclusive:mode?.isTaxInclusive ?: 'N'])
}
def templates=ec.entity.find('zenith.erp.pos.PosReceiptTemplate').condition('organizationPartyId',scope.organizationPartyId)
    .condition('isActive','Y').orderBy('-isDefault,templateId').list()
def billing=sessionId ? ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',sessionId).call() : null
if(ec.message.hasError()) return
def facilityId=billing?.terminal?.facilityId ?: selected.table?.facilityId
if(billing && selected.table && selected.table.facilityId!=facilityId) { ec.message.addError('Choose a table at this terminal shop.'); return }
def tpl=templates.find { facilityId && it.facilityId==facilityId } ?: templates.find { !it.facilityId }
def state=tpl?.taxRegistrationNumber?.size()==15 ? tpl.taxRegistrationNumber.substring(0,2) : null
if(!state) {
    def terminals=ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',scope.organizationPartyId).condition('isActive','Y')
    if(facilityId)terminals.condition('facilityId',facilityId)
    def states=terminals.list().collect { it.stateCode ?: it.regionGeoId }.findAll { it }.unique()
    if(states.size()==1)state=states[0]
}
if (!(taxOn in ['Y','N'])) { ec.message.addError('Choose a valid tax setting.'); return }
def tax=taxOn=='Y' ? ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([organizationPartyId:scope.organizationPartyId,
    items:taxInputs,originRegionGeoId:state,destinationRegionGeoId:state,transactionType:'SALE']).call() : null
if(ec.message.hasError()) return
def sumTax=[:], lines=[]
products.eachWithIndex { row,i ->
    def ti=tax?.taxedItems?.getAt(i)
    (ti?.taxBreakdowns ?: []).each { b -> sumTax[b.taxName]=(sumTax[b.taxName] ?: 0)+(b.taxAmount ?: 0) }
    lines.add([productId:row.product.productId,name:row.product.productName ?: row.product.productId,code:row.product.pseudoId ?: row.product.productId,qty:row.qty,rate:row.price,
        total:(ti?.taxableAmount != null ? ti.taxableAmount : row.price*row.qty-row.discount),tax:(ti?.totalTaxAmount ?: 0),discount:row.discount,
        uom:['OTH_ea':'Nos','WT_kg':'kg','WT_g':'g','VLIQ_L':'L','VLIQ_ml':'ml'][row.product.amountUomId] ?: ''])
}
def party=ec.entity.find('mantle.party.Organization').condition('partyId',scope.organizationPartyId).one()
def person=ec.entity.find('mantle.party.Person').condition('partyId',ec.user.userAccount?.partyId).one()
def options=ec.service.sync().name('zenith.pos.ReceiptTemplateServices.resolve#ReceiptOptions')
    .parameters([storedJson:tpl?.receiptOptionsJson,receiptDesign:'normal']).call().options
// Match recalculate#TransactionTotals: round the customer payable once, after GST.
def subtotal=taxOn=='Y' ? (tax.totalTaxableAmount ?: 0) as BigDecimal : (products.sum { it.price*it.qty-it.discount } ?: BigDecimal.ZERO) as BigDecimal
def grand=taxOn=='Y' ? (tax.totalAmount ?: 0) as BigDecimal : subtotal
def payable=grand.setScale(0,java.math.RoundingMode.HALF_UP)
receipt=[success:true,preview:true,store:[name:tpl?.companyName ?: party?.organizationName ?: 'Store',
    address:tpl ? [tpl.addressLine1,tpl.addressLine2,tpl.city,tpl.state,tpl.pincode].findAll{it}.join(', ') : '',
    phone:tpl?.phone ?: '',email:tpl?.email ?: '',taxReg:tpl?.taxRegistrationNumber ?: '',receiptWidth:tpl?.receiptWidth ?: '80mm',
    headerText:tpl?.headerText ?: '',footerText:tpl?.footerText ?: '',termsText:tpl?.termsText ?: '',
    showLogo:tpl?.showLogo ?: 'N',logoUrl:tpl?.logoUrl ?: '',showTaxBreakdown:tpl?.showTaxBreakdown ?: 'Y',
    showDiscount:tpl?.showDiscount ?: 'Y',showCustomerInfo:tpl?.showCustomerInfo ?: 'Y',showPaymentDetails:'N',showItemTax:tpl?.showItemTax ?: 'N'],
    options:options,bill:[number:'UNPAID ORDER',date:ec.l10n.format(ec.user.nowTimestamp,'dd/MM/yyyy hh:mm a'),
    cashier:person ? [person.firstName,person.lastName].findAll{it}.join(' ') : '',customer:'Walk-In Customer',
    table:selected.table?.tableNumber ?: '',orderType:orderType ?: 'Dine In',taxOn:taxOn,salesModeId:salesModeId,waiterId:waiterId,waiter:waiter?.waiterName],items:lines,
    summary:[subtotal:subtotal,tax:(tax?.totalTaxAmount ?: 0),discount:0,roundOff:payable-grand,total:payable,
        totalQty:products.sum { it.qty },itemCount:lines.size(),taxBreakdown:sumTax.collect { n,v -> [name:n,amount:v] }],
    payments:[],saving:0,change:0,notes:notes ?: '']

def k=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',kotId).condition('organizationPartyId',scope.organizationPartyId).one()
if(!k) { ec.message.addError('Kitchen order not found in this shop.'); return }
if(kind in ['bill','orderBill']) {
    def tx=k.transactionId ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',k.transactionId)
        .condition('organizationPartyId',scope.organizationPartyId).condition('statusId','PtCompleted').one() : null
    if(tx && tx.transactionNumber) record=ec.service.sync().name('zenith.pos.PosServices.get#PosReceiptData').parameter('transactionId',tx.transactionId).call().receipt
    else if(kind=='orderBill' && k.orderReceiptJson) {
        record=new groovy.json.JsonSlurper().parseText(k.orderReceiptJson)
        for(def item in record.items ?: []) {
            def product=item.productId ? ec.entity.find('mantle.product.Product').condition('productId',item.productId)
                .condition('ownerPartyId',scope.organizationPartyId).one() : null
            item.name=product?.printName ?: item.name
        }
    }
    else { ec.message.addError('No finalized customer bill is linked to this KOT. Older orders without a saved pricing snapshot cannot print an unpaid bill.'); return }
} else {
    record=[number:k.kotNumber ?: k.kotId,date:ec.l10n.format(k.kotDate,'dd/MM/yyyy hh:mm a'),table:k.tableNumber ?: '-',
        notes:k.notes ?: '',waiter:k.waiterName ?: '',items:ec.entity.find('zenith.erp.pos.KotItem').condition('kotId',k.kotId)
            .orderBy('kotItemSeqId').list().collect { [name:it.productName ?: it.productId,qty:it.quantity,instructions:it.specialInstructions ?: ''] }]
}
